import{_ as s,C as t,o as l,c as i,a4 as n,j as d,E as o}from"./chunks/framework.BUqnS5H7.js";const k=JSON.parse('{"title":"Redo Log","description":"","frontmatter":{},"headers":[],"relativePath":"mysql/02-innodb-internals/chapter-04-redo-log.md","filePath":"mysql/02-innodb-internals/chapter-04-redo-log.md"}'),r={name:"mysql/02-innodb-internals/chapter-04-redo-log.md"},c={"data-src-line":"56","data-src-file":"mysql/02-innodb-internals/chapter-04-redo-log.md"};function p(h,a,g,m,b,y){const e=t("SvgDiagram");return l(),i("div",null,[a[0]||(a[0]=n(`<h1 id="redo-log" tabindex="-1" data-src-line="1" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">Redo Log <a class="header-anchor" href="#redo-log" aria-label="Permalink to &quot;Redo Log&quot;">​</a></h1><blockquote data-src-line="3" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md"><p data-src-line="3" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">一条 <code>UPDATE</code> 执行完，<code>COMMIT</code> 返回「成功」——这时数据真的写进磁盘了吗？如果立刻断电，这条修改还在吗？InnoDB 的回答是「在」。它靠的不是把每一行数据都刷进表空间，而是一份按顺序追加的小日志：Redo Log。理解了它，就理解了「为什么事务提交后数据不丢」和「为什么 MySQL 的写性能可以接受」这两个问题其实共享同一个答案。</p></blockquote><h2 id="_1-为什么需要-redo-log" tabindex="-1" data-src-line="5" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">1. 为什么需要 Redo Log <a class="header-anchor" href="#_1-为什么需要-redo-log" aria-label="Permalink to &quot;1. 为什么需要 Redo Log&quot;">​</a></h2><h3 id="_1-1-一个「断电后数据还在」的现象" tabindex="-1" data-src-line="7" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">1.1 一个「断电后数据还在」的现象 <a class="header-anchor" href="#_1-1-一个「断电后数据还在」的现象" aria-label="Permalink to &quot;1.1 一个「断电后数据还在」的现象&quot;">​</a></h3><p data-src-line="9" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">先看一个场景。执行一条更新，然后立刻拔掉服务器电源：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">BEGIN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">UPDATE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> accounts </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> balance </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1000</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">COMMIT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 返回成功</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 此刻断电</span></span></code></pre></div><p data-src-line="18" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">重启后，<code>id=1</code> 的 <code>balance</code> 是 1000 还是原来的值？答案是 <strong>1000</strong>——只要事务返回了提交成功，这条修改就不会因为断电而丢失。</p><p data-src-line="20" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">但直觉上这是反常识的：磁盘写入有先后，<code>COMMIT</code> 返回时，那行数据所在的 16KB 数据页可能还躺在内存的 Buffer Pool 里，根本没写回磁盘。为什么它「承诺」的数据还能在断电后找回来？</p><p data-src-line="22" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">答案分两层：<strong>数据页靠 Redo Log 重放找回来</strong>，<strong>Redo Log 本身靠顺序写保证在 COMMIT 前真正落盘</strong>。下面先把「为什么需要一份单独的日志」讲清楚。</p><h3 id="_1-2-为什么不能直接把数据页写回磁盘" tabindex="-1" data-src-line="24" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">1.2 为什么不能直接把数据页写回磁盘 <a class="header-anchor" href="#_1-2-为什么不能直接把数据页写回磁盘" aria-label="Permalink to &quot;1.2 为什么不能直接把数据页写回磁盘&quot;">​</a></h3><p data-src-line="26" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">先退一步问：没有 Redo Log，MySQL 能不能保证持久性？</p><p data-src-line="28" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">能，但代价很高。数据页的存放位置是分散的——一条 <code>UPDATE</code> 可能同时改到聚簇索引页、二级索引页、回滚段页，这些页在表空间文件里彼此相距很远。每提交一个事务，都要把这些页逐个「随机写」回磁盘，而随机写（磁头寻道 / SSD 随机小写）是磁盘上最慢的操作。</p><p data-src-line="30" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">更麻烦的是「部分写」：一个 16KB 的页只写了一半就断电，这一半数据既不是旧值也不是新值，整页就废了。</p><p data-src-line="32" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">Redo Log 的思路是绕开这两点：<strong>修改发生时，不急着把数据页落盘，而是先把「改了什么」按顺序追加到一份日志里。</strong> 顺序追加是磁盘最快的写入方式，一次 <code>COMMIT</code> 只需要把一小段日志追加写进文件末尾，而不是把一堆散落的数据页随机写回。数据页可以晚点、甚至批量地异步刷盘。</p><p data-src-line="34" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">这就是 WAL（Write-Ahead Logging，先写日志）的核心动机：<strong>用一次廉价的顺序写，换取「修改已持久化」的承诺，把昂贵的随机写推迟到后台批量完成。</strong></p><h3 id="_1-3-wal-原理-先写日志-再写数据" tabindex="-1" data-src-line="36" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">1.3 WAL 原理：先写日志，再写数据 <a class="header-anchor" href="#_1-3-wal-原理-先写日志-再写数据" aria-label="Permalink to &quot;1.3 WAL 原理：先写日志，再写数据&quot;">​</a></h3><p data-src-line="38" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">WAL 规则只有一条：<strong>在把数据页刷盘之前，必须先把它对应的日志记录刷盘。</strong></p><p data-src-line="40" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">顺序很重要，反了就失效。设想「先刷数据页、后写日志」：数据页已经落盘了，日志还没写，此时断电，日志里没有这次修改的记录——但数据页已经在磁盘上了，表面看没丢。问题出在「日志是唯一可信的重放依据」这一点：崩溃恢复时，InnoDB 只相信日志，用日志去校准数据页。如果数据页写在了日志前面，恢复时就无法判断这个页到底该是旧值还是新值。</p><p data-src-line="42" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">反过来「先写日志、后刷数据页」就自洽了：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>事务修改流程：</span></span>
<span class="line"><span>1. 在 Buffer Pool 中修改数据页（内存操作，快）</span></span>
<span class="line"><span>2. 把这次修改写成 Redo Log 记录，追加到 Log Buffer</span></span>
<span class="line"><span>3. 事务提交时，按 innodb_flush_log_at_trx_commit 的策略把 Log Buffer 刷盘</span></span>
<span class="line"><span>4. 数据页在后台由 Checkpoint / 刷脏页线程异步落盘</span></span></code></pre></div><p data-src-line="52" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">关键在于：<strong>第 2 步的日志一旦落盘，第 4 步的数据页哪怕永远不写，崩溃后也能靠日志重放出来。</strong> 数据页落盘晚一点没关系，日志落盘才是「提交成功」的真正边界。</p><h2 id="_2-日志的物理基础" tabindex="-1" data-src-line="54" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">2. 日志的物理基础 <a class="header-anchor" href="#_2-日志的物理基础" aria-label="Permalink to &quot;2. 日志的物理基础&quot;">​</a></h2>`,22)),d("p",c,[o(e,{src:"/mysql/02-innodb-internals-chapter-04-redo-log.svg",alt:"Redo Log 全景：Log Buffer / 循环缓冲 / 记录格式 / LSN / Checkpoint"})]),a[1]||(a[1]=n(`<h3 id="_2-1-lsn-redo-log-的坐标轴" tabindex="-1" data-src-line="58" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">2.1 LSN：Redo Log 的坐标轴 <a class="header-anchor" href="#_2-1-lsn-redo-log-的坐标轴" aria-label="Permalink to &quot;2.1 LSN：Redo Log 的坐标轴&quot;">​</a></h3><p data-src-line="60" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">要讲清崩溃恢复和 Checkpoint，得先引入一个贯穿全篇的量：LSN（Log Sequence Number，日志序列号）。</p><p data-src-line="62" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">LSN 是 Redo Log 的字节偏移量，单调递增。每写一个字节的日志，LSN 就加一。它有三个关键落脚点：</p><ul data-src-line="64" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md"><li data-src-line="64" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md"><strong>全局当前 LSN</strong>：Redo Log 写到了哪个字节位置。</li><li data-src-line="65" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md"><strong>数据页上的 <code>FIL_PAGE_LSN</code></strong>：每个数据页的 File Header 里记录「我最后一次被修改时，对应的日志 LSN 是多少」。</li><li data-src-line="66" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md"><strong>Checkpoint LSN</strong>：已刷盘数据页对应的最大 LSN。</li></ul><p data-src-line="68" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">这三个值一比较，就能回答「这个数据页需不需要重放」：<strong>如果某页的 <code>FIL_PAGE_LSN</code> 小于某条日志记录的 LSN，说明这条日志对应的修改还没刷进这个页，崩溃恢复时就要重放。</strong></p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>LSN 单调递增 →</span></span>
<span class="line"><span>0 ──────────── checkpoint LSN ──────────── 当前 LSN</span></span>
<span class="line"><span>     （这部分日志已刷盘）      （这部分日志可能还没刷进数据页）</span></span></code></pre></div><p data-src-line="76" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">用 LSN 这把尺子，Checkpoint 和崩溃恢复就有了统一的度量，不再需要逐页猜测。</p><h3 id="_2-2-redo-log-的物理结构与记录格式" tabindex="-1" data-src-line="78" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">2.2 Redo Log 的物理结构与记录格式 <a class="header-anchor" href="#_2-2-redo-log-的物理结构与记录格式" aria-label="Permalink to &quot;2.2 Redo Log 的物理结构与记录格式&quot;">​</a></h3><p data-src-line="80" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">Redo Log 在磁盘上的形态，随 MySQL 版本有变化：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- MySQL 8.0.30 之前：固定大小的一组文件</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SHOW VARIABLES </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">LIKE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;innodb_log_file_size&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;        </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 单个文件大小</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SHOW VARIABLES </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">LIKE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;innodb_log_files_in_group&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 文件个数</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- MySQL 8.0.30 之后：统一容量，自动管理，存于 #innodb_redo 目录</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SHOW VARIABLES </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">LIKE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;innodb_redo_log_capacity&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 总容量</span></span></code></pre></div><p data-src-line="91" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">文件被组织成一个<strong>循环缓冲区</strong>：写满一圈就回到开头覆盖。覆盖的前提是「被覆盖的那部分日志对应的数据页已经刷盘」，这正是 Checkpoint 的职责（见 §3.2）。</p><p data-src-line="93" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">每条 Redo Log 记录本身是「物理日志」——记录的不是 SQL，而是「哪个页的哪个位置改成了什么」：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────┬────────────────────────────────┐</span></span>
<span class="line"><span>│ Type         │  日志类型（MLOG_XXX）           │</span></span>
<span class="line"><span>│ Space ID     │  表空间 ID                     │</span></span>
<span class="line"><span>│ Page Number  │  页号                          │</span></span>
<span class="line"><span>│ Offset       │  页内偏移                      │</span></span>
<span class="line"><span>│ Data         │  修改的数据                    │</span></span>
<span class="line"><span>└──────────────┴────────────────────────────────┘</span></span></code></pre></div><p data-src-line="105" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md"><code>MLOG_1BYTE</code>、<code>MLOG_2BYTE</code> 这类类型名表明它精确到「字节级」：崩溃恢复时不需要重算，照着记录把字节写回指定位置即可。这种「物理」特性是 Redo Log 能快速重放的原因，也是它和 Binlog（逻辑日志）最本质的区别。</p><h3 id="_2-3-mtr-保证「一组修改」的原子性" tabindex="-1" data-src-line="107" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">2.3 MTR：保证「一组修改」的原子性 <a class="header-anchor" href="#_2-3-mtr-保证「一组修改」的原子性" aria-label="Permalink to &quot;2.3 MTR：保证「一组修改」的原子性&quot;">​</a></h3><p data-src-line="109" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">一条 SQL 往往涉及多处修改，比如插入一条记录，要同时改：</p><ol data-src-line="111" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md"><li data-src-line="111" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">数据页（写入这条记录）；</li><li data-src-line="112" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">页的 Page Header（记录数 +1）；</li><li data-src-line="113" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">可能还有系统页（更新 <code>MAX_TRX_ID</code>）。</li></ol><p data-src-line="115" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">这三处修改必须「要么都恢复，要么都不恢复」。如果崩溃发生在写了一半的时候，只恢复了数据页的插入、没恢复 Page Header 的计数，页就处于自相矛盾的状态。</p><p data-src-line="117" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">InnoDB 用 <strong>MTR（Mini-Transaction，迷你事务）</strong> 解决：MTR 把「一组逻辑上不可分割的修改」打包成一批 Redo Log 记录，这一批作为一个整体写入。崩溃恢复时，MTR 的日志要么整段重放，要么整段跳过，不会出现「重放到一半」的中间态。</p><p data-src-line="119" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">可以把 MTR 理解为 Redo Log 层的原子单位——事务（Transaction）是业务层的原子单位，MTR 是物理层的原子单位，一个事务通常由多个 MTR 组成。</p><h2 id="_3-刷盘与空间回收" tabindex="-1" data-src-line="121" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">3. 刷盘与空间回收 <a class="header-anchor" href="#_3-刷盘与空间回收" aria-label="Permalink to &quot;3. 刷盘与空间回收&quot;">​</a></h2><h3 id="_3-1-log-buffer-与刷盘策略" tabindex="-1" data-src-line="123" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">3.1 Log Buffer 与刷盘策略 <a class="header-anchor" href="#_3-1-log-buffer-与刷盘策略" aria-label="Permalink to &quot;3.1 Log Buffer 与刷盘策略&quot;">​</a></h3><p data-src-line="125" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">日志不是一条一条直接写磁盘的。修改产生后，Redo Log 记录先写入内存里的 <strong>Log Buffer</strong>，再按策略批量刷盘：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SHOW VARIABLES </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">LIKE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;innodb_log_buffer_size&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- Log Buffer 大小，默认 16MB</span></span></code></pre></div><p data-src-line="131" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">Log Buffer 刷盘的时机有四种：事务提交时、Log Buffer 写满一半时、后台线程每秒一次、Checkpoint 时。其中「事务提交时怎么刷」由参数 <code>innodb_flush_log_at_trx_commit</code> 控制，这是全篇最需要理解的一个参数：</p><table tabindex="0"><thead data-src-line="133" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md"><tr data-src-line="133" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md"><th style="text-align:left;">取值</th><th style="text-align:left;">提交时行为</th><th style="text-align:left;">断电后可能丢多少数据</th></tr></thead><tbody data-src-line="135" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md"><tr data-src-line="135" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md"><td style="text-align:left;"><code>0</code></td><td style="text-align:left;">不主动刷，仅靠后台每秒刷</td><td style="text-align:left;">最近 <strong>1 秒</strong> 的事务</td></tr><tr data-src-line="136" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md"><td style="text-align:left;"><code>1</code></td><td style="text-align:left;">每次提交都刷盘（<code>fsync</code>）</td><td style="text-align:left;"><strong>0</strong>（提交即落盘）</td></tr><tr data-src-line="137" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md"><td style="text-align:left;"><code>2</code></td><td style="text-align:left;">每次提交写 OS 缓存，靠 OS 每秒刷</td><td style="text-align:left;">最近 <strong>1 秒</strong> 的事务</td></tr></tbody></table><p data-src-line="139" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">三个值的差异，本质在「刷」这个词落到哪一层：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Log Buffer（内存） → OS Page Cache（操作系统缓存） → 磁盘</span></span>
<span class="line"><span>       └── 值 2 只走到这里        └── 值 1 走到这里（fsync）</span></span>
<span class="line"><span>值 0：哪都不主动走，等后台每秒 fsync</span></span></code></pre></div><p data-src-line="147" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">理解数据丢失边界的关键：<strong>值 <code>0</code> 和 <code>2</code> 的区别不在丢不丢，而在「丢失时丢的是什么粒度」。</strong></p><ul data-src-line="149" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md"><li data-src-line="149" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">值 <code>0</code>：事务提交了，日志还停在 Log Buffer，MySQL 进程崩了（不只是断电）就直接没了。</li><li data-src-line="150" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">值 <code>2</code>：日志已经交给 OS 缓存，MySQL 进程崩了不影响（OS 缓存还在），只有<strong>整机断电</strong>才可能丢 OS 缓存里那 1 秒。</li><li data-src-line="151" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">值 <code>1</code>：<code>fsync</code> 返回后，日志已在磁盘物理扇区上，MySQL 崩溃、断电都不丢。</li></ul><p data-src-line="153" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">所以「值 0 和值 2 都丢 1 秒」是简化说法，严谨的边界是：<strong>值 0 怕 MySQL 崩溃，值 2 只怕整机断电，值 1 什么都不怕（代价是每次提交都 fsync，性能最差）。</strong></p><p data-src-line="155" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">生产环境的常见选择：默认 <code>1</code> 保安全；对性能极度敏感、又能容忍 1 秒丢失的日志类业务，可降为 <code>2</code>；<code>0</code> 基本不推荐。</p><h3 id="_3-2-checkpoint-redo-log-的空间回收" tabindex="-1" data-src-line="157" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">3.2 Checkpoint：Redo Log 的空间回收 <a class="header-anchor" href="#_3-2-checkpoint-redo-log-的空间回收" aria-label="Permalink to &quot;3.2 Checkpoint：Redo Log 的空间回收&quot;">​</a></h3><p data-src-line="159" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">Redo Log 是循环写的，容量有限。它覆盖旧日志的前提，是「旧日志对应的数据页已经刷盘」。这个「刷盘推进到哪里」的标记，就是 <strong>Checkpoint</strong>。</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>             checkpoint LSN</span></span>
<span class="line"><span>                  ↓</span></span>
<span class="line"><span>redo 文件: [已刷盘部分][未刷盘部分][空闲]</span></span>
<span class="line"><span>             ↑ 可被覆盖     ↑ 崩溃恢复要用的</span></span></code></pre></div><p data-src-line="168" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">Checkpoint 做的事：把 Buffer Pool 里「LSN 小于某个值」的脏页批量刷盘，然后把 Checkpoint LSN 推进到那个值。推进之后，Checkpoint LSN 之前的日志就可以安全覆盖了。</p><p data-src-line="170" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">它直接决定了两个关键指标：</p><ul data-src-line="172" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md"><li data-src-line="172" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md"><strong>崩溃恢复速度</strong>：Checkpoint 推进得越勤，恢复时要重放的日志越少，恢复越快；但刷盘越频繁，正常运行时开销越大。</li><li data-src-line="173" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md"><strong>Redo Log 会不会写满</strong>：如果脏页刷盘速度跟不上日志产生速度，Checkpoint LSN 停住不动，未刷盘部分越积越多，最终填满整个 Redo Log。一旦写满，InnoDB 只能暂停写入、强制刷脏页，表现为写入吞吐骤降。</li></ul><p data-src-line="175" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">这正是「为什么不能有长事务、不能有长时间刷不动脏页」的底层原因之一：<strong>Redo Log 空间被未刷盘的日志占满，写路径被 Checkpoint 卡死。</strong></p><h2 id="_4-崩溃恢复" tabindex="-1" data-src-line="177" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">4. 崩溃恢复 <a class="header-anchor" href="#_4-崩溃恢复" aria-label="Permalink to &quot;4. 崩溃恢复&quot;">​</a></h2><h3 id="_4-1-崩溃恢复的完整流程" tabindex="-1" data-src-line="179" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">4.1 崩溃恢复的完整流程 <a class="header-anchor" href="#_4-1-崩溃恢复的完整流程" aria-label="Permalink to &quot;4.1 崩溃恢复的完整流程&quot;">​</a></h3><p data-src-line="181" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">把前面几节串起来，MySQL 崩溃重启后做这样几件事：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 找到最近一次 Checkpoint LSN</span></span>
<span class="line"><span>2. 从 Checkpoint LSN 开始，向后扫描 Redo Log</span></span>
<span class="line"><span>3. 对每条日志：若目标数据页的 FIL_PAGE_LSN &lt; 这条日志的 LSN，就重放这条日志</span></span>
<span class="line"><span>4. 重放完成后，通过 Undo Log 把「未提交事务」的修改回滚掉</span></span></code></pre></div><p data-src-line="190" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">第 3 步里 <code>FIL_PAGE_LSN</code> 的比较，正是 §2.1 那把尺子的落地：数据页上记的 LSN 比日志旧，说明日志对应的修改没刷进页里，需要重放；比日志新或相等，说明页已经是新状态，跳过即可。这个判断让恢复变得幂等——重复重放同一段日志也不会出错。</p><p data-src-line="192" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">第 4 步引出了 Redo 与 Undo 的分工：<strong>Redo 负责「把已提交的修改找回来」，Undo 负责「把未提交的修改抹掉」。</strong> 崩溃时，日志里既有已提交事务的修改，也有未提交事务的修改，重放会把两者都恢复出来，再由 Undo 回滚掉未提交的那部分。Undo 的机制见 <a href="./chapter-05-undo-log.html">Undo Log</a>。</p><h2 id="_5-与-binlog-的关系" tabindex="-1" data-src-line="194" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">5. 与 Binlog 的关系 <a class="header-anchor" href="#_5-与-binlog-的关系" aria-label="Permalink to &quot;5. 与 Binlog 的关系&quot;">​</a></h2><h3 id="two-phase-commit" tabindex="-1" data-src-line="196" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">5.1 两阶段提交：Redo Log 与 Binlog 的一致性 <a class="header-anchor" href="#two-phase-commit" aria-label="Permalink to &quot;5.1 两阶段提交：Redo Log 与 Binlog 的一致性 {#two-phase-commit}&quot;">​</a></h3><p data-src-line="198" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">Redo Log 只解决「InnoDB 自己崩溃不丢数据」。但 MySQL 还有第二份日志——<strong>Binlog</strong>（Server 层，用于主从复制和按时间点恢复）。于是每个事务的提交，都要同时保证两份日志一致：Redo Log 里有，Binlog 里也得有。</p><p data-src-line="200" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">难点在于：写两份日志是两次独立的磁盘写，崩溃可能发生在「只写完了一份」的瞬间。如果不管先后顺序，都会出问题：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>方案一：先写 Redo，再写 Binlog</span></span>
<span class="line"><span>  写完 Redo 后崩溃 → 主库恢复了该事务，但 Binlog 里没有</span></span>
<span class="line"><span>  → 从库基于 Binlog 重放，少了一条数据，主从不一致</span></span>
<span class="line"><span></span></span>
<span class="line"><span>方案二：先写 Binlog，再写 Redo</span></span>
<span class="line"><span>  写完 Binlog 后崩溃 → Binlog 里有，但 Redo 没有</span></span>
<span class="line"><span>  → 主库回滚了该事务，但从库重放 Binlog 会多出一条数据，主从不一致</span></span></code></pre></div><p data-src-line="212" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">InnoDB 用<strong>两阶段提交</strong>解决这个「两份日志无法原子写」的难题。事务提交分三步：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. InnoDB：写 Redo Log，标记为 prepare（准备）状态</span></span>
<span class="line"><span>2. Server：写 Binlog</span></span>
<span class="line"><span>3. InnoDB：把 Redo Log 标记为 commit（提交）状态</span></span></code></pre></div><p data-src-line="220" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">崩溃恢复时，扫描 Redo Log 里处于 <code>prepare</code> 状态的事务，用「Binlog 是否完整」来裁决它的命运：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>崩溃恢复对 prepare 事务的判定：</span></span>
<span class="line"><span>- 对应 Binlog 完整（能查到该事务的 XID 事件）→ 提交（补写 redo commit）</span></span>
<span class="line"><span>- 对应 Binlog 不完整（没有 XID）→ 回滚</span></span></code></pre></div><p data-src-line="228" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">为什么这个规则能保证一致？核心观察是：<strong>Binlog 的写是原子标志。</strong> 只要 Binlog 完整落地，就说明这个事务「对外已经算提交」了，从库迟早会重放到它，主库必须跟着提交；只要 Binlog 没落地，就说明事务还没对外生效，主库回滚它，从库也不会知道。于是无论崩溃发生在第 1 步和第 2 步之间，还是第 2 步和第 3 步之间，主从最终都收敛到同一状态。</p><p data-src-line="230" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">Binlog 的格式、事件类型与参数见 <a href="./chapter-06-binlog.html">Binlog</a>。</p><h3 id="redo-vs-binlog" tabindex="-1" data-src-line="232" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">5.2 Redo Log 与 Binlog 的区别 <a class="header-anchor" href="#redo-vs-binlog" aria-label="Permalink to &quot;5.2 Redo Log 与 Binlog 的区别 {#redo-vs-binlog}&quot;">​</a></h3><table tabindex="0"><thead data-src-line="234" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md"><tr data-src-line="234" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md"><th style="text-align:left;">对比项</th><th style="text-align:left;">Redo Log</th><th style="text-align:left;">Binlog</th></tr></thead><tbody data-src-line="236" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md"><tr data-src-line="236" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md"><td style="text-align:left;">所属层</td><td style="text-align:left;">InnoDB 存储引擎层</td><td style="text-align:left;">MySQL Server 层</td></tr><tr data-src-line="237" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md"><td style="text-align:left;">记录内容</td><td style="text-align:left;">物理日志（哪个页哪段字节改成什么）</td><td style="text-align:left;">逻辑日志（SQL 语句或行变更）</td></tr><tr data-src-line="238" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md"><td style="text-align:left;">写入方式</td><td style="text-align:left;">循环写，固定容量</td><td style="text-align:left;">追加写，文件轮转</td></tr><tr data-src-line="239" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md"><td style="text-align:left;">主要用途</td><td style="text-align:left;">崩溃恢复</td><td style="text-align:left;">主从复制、按时间点恢复</td></tr><tr data-src-line="240" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md"><td style="text-align:left;">事务边界</td><td style="text-align:left;">无明确的 BEGIN/COMMIT 标记</td><td style="text-align:left;">有明确事务边界与 XID</td></tr></tbody></table><h2 id="_6-最佳实践" tabindex="-1" data-src-line="242" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md">6. 最佳实践 <a class="header-anchor" href="#_6-最佳实践" aria-label="Permalink to &quot;6. 最佳实践&quot;">​</a></h2><ol data-src-line="244" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md"><li data-src-line="244" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md"><strong>数据安全优先用「双 1」</strong>：<code>innodb_flush_log_at_trx_commit=1</code> + <code>sync_binlog=1</code>，提交即落盘，崩溃不丢。</li><li data-src-line="245" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md"><strong>Redo Log 容量设置</strong>：写密集型业务给足空间（如 2G-4G），避免写满触发 Checkpoint 卡顿。</li><li data-src-line="246" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md"><strong>SSD 环境</strong>：Redo Log 与数据文件同盘即可，顺序写的优势在 SSD 上依然成立。</li><li data-src-line="247" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md"><strong>监控写入量</strong>：<code>SHOW GLOBAL STATUS LIKE &#39;Innodb_os_log_written&#39;;</code> 观察日志产生速率。</li><li data-src-line="248" data-src-file="mysql/02-innodb-internals/chapter-04-redo-log.md"><strong>避免长事务与脏页堆积</strong>：长事务让 Undo 无法清理、脏页迟迟刷不干净，间接拖慢 Checkpoint。</li></ol>`,60))])}const q=s(r,[["render",p]]);export{k as __pageData,q as default};
